from pathlib import Path
import html,json,re,xml.etree.ElementTree as ET
ROOT=Path.cwd();OUT=ROOT/'outputs'
def p(s):return '<p>'+s+'</p>'
def pre(s,kind=''):return '<pre'+(' data-language="'+kind+'"' if kind else '')+'><code>'+html.escape(s)+'</code></pre>'
def table(head,rows):return '<div class="reference-table"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def sec(id,title,body):return '<section><h2 id="'+id+'">'+title+'</h2>'+body+'</section>'
def link(f,l,a=''):return '<a href="'+f+'.html'+('#'+a if a else '')+'">'+l+'</a>'
def figure(id,title,boxes,edges,caption):
 h=max(b[1]+b[3] for b in boxes)+35
 s=f'<figure class="concept-figure"><svg viewBox="0 0 900 {h}" role="img" aria-labelledby="{id}-title {id}-desc" xmlns="http://www.w3.org/2000/svg"><title id="{id}-title">{title}</title><desc id="{id}-desc">{caption}</desc><defs><marker id="{id}-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#477b9e"/></marker></defs>'
 for a,b,c,d in edges:s+=f'<path d="M{a} {b} L{c} {d}" class="svg-link" marker-end="url(#{id}-arrow)"/>'
 for x,y,w,z,t,n in boxes:s+=f'<rect x="{x}" y="{y}" width="{w}" height="{z}" rx="9" class="svg-node"/><text x="{x+14}" y="{y+25}" class="svg-text">{html.escape(t)}</text><text x="{x+14}" y="{y+48}" class="svg-note">{html.escape(n)}</text>'
 return s+'</svg><figcaption>'+caption+'</figcaption></figure>'
def sequence(id,title,events,caption):
 h=100+len(events)*56
 s=f'<figure class="concept-figure"><svg viewBox="0 0 900 {h}" role="img" aria-labelledby="{id}-title" xmlns="http://www.w3.org/2000/svg"><title id="{id}-title">{title}</title><defs><marker id="{id}-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#477b9e"/></marker></defs><text x="85" y="30" class="svg-title">客户端 Client</text><text x="690" y="30" class="svg-title">服务器 Server</text><path d="M150 50 V{h-20} M750 50 V{h-20}" class="svg-dash"/>'
 for i,(d,t) in enumerate(events):
  y=88+i*56;a,b=(150,750) if d=='>' else (750,150)
  s+=f'<text x="450" y="{y-12}" text-anchor="middle" class="svg-text">{html.escape(t)}</text><path d="M{a} {y} H{b}" class="svg-link" marker-end="url(#{id}-arrow)"/>'
 return s+'</svg><figcaption>'+caption+'</figcaption></figure>'
pages=[]
def page(f,t,g,sections,source,nexts):
 common=sec('reading','阅读位置与版本',p('上级：'+(link('standard-library-overview','标准文库') if f=='standard-part-7-2' else link('standard-part-7-2','第 7-2 部分：ACSI'))+'。按“概念 → 属性与服务 → SCD 证据 → 工程使用”阅读。')+p('标准基线：DL/T 860.72—2004（等同 IEC 61850-7-2:2003）；参考 SCD 为 SCL 2007 B4。抽象模型、协议映射、XML 配置和设备运行值分别解释。本文为原创导读，工程摘录保留源文件关键字与名称，不是完整可投产配置。'))
 sources=sec('sources','来源与继续阅读',p('原文定位：'+source.rstrip('。')+'。参考文件：860[1].7-2.pdf（123 个 PDF 页），南雷变2026041614.scd。PDF 页指文件顺序页；正文印刷页通常为 PDF 页减 5。')+p('原 PDF：D:/IEC61850/IEC61850标准[中文.完整版]/860[1].7-2.pdf。本站离线阅读不依赖原 PDF 目录。')+p('继续阅读：'+' · '.join(link(a,b) for a,b in nexts)))
 content='<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+t+'｜IEC 61850 离线知识库</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="top"><div class="chapter"><p class="section-kicker">'+g+' · 第 7-2 部分专题</p><h1>'+t+'</h1><p>从信息对象，理解服务、配置引用和运行行为。</p></div></header><main class="chapter">'+common+'\n'+'\n'.join(sections)+sources+'</main><footer class="footer">IEC 61850 离线知识库 · 标准、映射、工程配置与运行证据分别核对</footer><script src="../assets/navigation.js"></script></body></html>\n'
 (OUT/'chapters'/f'{f}.html').write_text(content,encoding='utf-8');pages.append((f,t,g))
