SERVICES=['GetServerDirectory','Associate','Abort','Release','GetLogicalDeviceDirectory','GetLogicalNodeDirectory','GetAllDataValues','GetDataValues','SetDataValues','GetDataDirectory','GetDataDefinition','GetDataSetValues','SetDataSetValues','CreateDataSet','DeleteDataSet','GetDataSetDirectory','SetDataValues (Substitution)','SelectActiveSG','SelectEditSG','SetSGValues','ConfirmEditSGValues','GetSGValues','GetSGCBValues','Report (BRCB)','GetBRCBValues','SetBRCBValues','Report (URCB)','GetURCBValues','SetURCBValues','GetLCBValues','SetLCBValues','QueryLogByTime','QueryLogAfter','GetLogStatusValues','SendGOOSEMessage','GetGoReference','GetGOOSEElementNumber','GetGoCBValues','SetGoCBValues','SendGSSEMessage','GetGsReference','GetGSSEDataOffset','GetGsCBValues','SetGsCBValues','SendMSVMessage','GetMSVCBValues','SetMSVCBValues','SendUSVMessage','GetUSVCBValues','SetUSVCBValues','Select','SelectWithValue','Cancel','Operate','CommandTermination','TimeActivatedOperate','GetFile','SetFile','DeleteFile','GetFileAttributeValues']
page('acsi-engineering-workflows','时间、文件与 ACSI 工程核查','工程应用',[
sec('time','1. 时间模型与时间同步',p('第 18 章把时间语义、表示、外部时源、站内时间服务器、同步协议和需要时间的 IED 组成一个模型。ACSI 规定 UTC 语义与品质，具体对时协议由 SCSM 定义。时间服务器可与 ACSI 客户/服务器部署在同一硬件中，但它们的角色不同。')+table(['组成','功能','使用场景 / SCD 边界'],[('外部时源','提供已知准确度的时间、闰秒信息和时源纪元','不能把 GPS 纪元直接当 1970 UTC 纪元；本模型不指定全部硬件接口'),('站内时间服务器','向 IED 提供同步时间','当前可用性和时源品质需要运行证据'),('时间同步协议','使客户和服务器的时钟协同','8-1 等定义适用机制；后续工程 PTP 属于实际采用规范，不写成此 2003 基线必选'),('时标语义','纪元秒、分数和品质','TimeStamp 类型和 TimeQuality；参见公共类型'),('时标表示','映射定义字节/字段','EntryTime 与 TimeStamp 未必同编码'),('时间使用者','产生或解释事件、报告、样本和预约动作','SCD 类型及选项只说明配置，不证明当前满足性能')])+figure('clock-model','外部时间到应用判断',[(30,20,840,70,'外部时源','准确度、闰秒信息和纪元'),(30,135,840,70,'时间服务器 + 实际同步机制','由采用的 SCSM 和工程方案定义'),(30,255,390,80,'IED 本地时钟与时标','UTC 语义、分数与时间品质'),(480,255,390,80,'客户 / 订户解释','事件排序、采样协作、预约控制')],[(445,90,445,135),(220,205,220,255),(675,205,675,255),(420,295,480,295)],'对时机制、时标内容和应用接受策略共同决定时间是否可用。')+p('SOE（Sequence of Events，事件顺序记录）跨设备排序，须考虑时间准确度和失步；两个相差很小的事件不能只凭显示小数位断定真实先后。SV 协作还需样本计数、采样率和同步；预约控制 operTim 需在正确时间且仍满足动作条件，不能只证明定时器已启动。')+table(['核查点','含义','常见误读'],[('ClockFailure','时源不可靠，基线要求忽略该 TimeStamp','数值能显示就认为有效'),('ClockNotSynchronized','没有与外部 UTC 同步','本地时钟仍在走就认为已对时'),('TimeAccuracy','相对 UTC 的准确度等级','当作采样周期或 UI 小数位'),('FractionOfSecond','可表示二进制分辨率','60 ns 等于设备测时误差'),('DATA.t / TimeOfEntry / TimeOfLog','分别按数据、报告缓冲和日志语义采用','当成完全相同的时间'),('sampleSynchronized 配置','携带/采用同步信息的 XML 配置线索','当作当前 SmpSynch=true')])),
sec('files','2. FILE 类与全部文件服务',p('第 20 章 FILE 是服务器文件存储中的有序、非结构化二进制字节流，可以包含程序、数据或二者。ACSI 定义传输与存储管理，不定义所有文件内部格式，也不把传输成功等同于设备成功加载配置。COMTRADE 等扰动记录的格式另有规范。')+table(['属性','基线类型 / 存在','值域 / 功能','表现样式 / SCD'],[('FileName','VISIBLE STRING255','文件存储中的名；分层路径和命名约束按映射','教学 /records/event001.dat；不是本站路径'),('FileSize[0..1]','INT32U；0～4294967295','以八位位组计的文件长度；生成中文件无法确定时另按实现解释','教学 2048 字节；SCD 无全文件目录'),('LastModified','原表 43：TimeStamp','最近修改时间','人可读日期只是显示形式，运行属性由服务返回')])+table(['服务','Request','Response+','Response− / 用法'],[('GetFile','FileName','File-Data（八位位组串）','ServiceError；从服务器向客户获取内容'),('SetFile','FileName + File-Data','请求成功','ServiceError；从客户向服务器传内容'),('DeleteFile','FileName','请求成功','ServiceError；删除允许删除的设备文件'),('GetFileAttributeValues','适用 FileName/选择范围，按模型和映射','FileName + FileAttribute[1..n]，含长度与修改时间','ServiceError；先确认目录和属性')])+p('源表部分否定参数写 ServerError，正文说明使用 ServiceError，本页按失败服务语义说明。分段传输、句柄及线上请求可能映射成多个具体服务，不虚构“单个 ACSI 服务必等于单个 MMS 包”。')+sequence('file-flow','文件读取的概念流程',[('>','GetServerDirectory {ObjectClass=FILE}'),('<','可见文件名列表'),('>','GetFileAttributeValues {FileName}'),('<','大小和最近修改时间'),('>','GetFile {FileName}'),('<','File-Data 或 ServiceError')],'原创教学流程；本站只有静态知识，不提供设备文件上传、下载或删除操作。')+p('参考 SCD 有 63 个 IED 的 Services 含 FileHandling。它是工程能力声明，不能证明任意目录可读、任意文件可写，也不能证明采用 FTP/HTTP。将 SCD 作为文件传给设备是否可用，必须按设备明确支持的工程流程确认。')),
sec('conformance','3. 附录 A：基本、模型、服务一致性声明',p('附录 A 是规范性附录，用声明回答“设备承担什么角色、采用哪个映射、实现哪些模型与服务/选项”。M=强制、O=可选、c 条件符号依所选功能决定；可选不等于厂家可随意违反已声明功能的行为。客户端和服务器、发布方和订户应分别声明。')+table(['原表 A.1 项目','声明内容','核查意义'],[('B11 / B12','TPAA 服务器侧 / 客户侧','不能只查服务器是否支持'),('B21～B24','8-1、9-1、9-2 或其他 SCSM','固定采用版本和映射，不混用字段'),('B31 / B32','GSE 发布侧 / 订户侧','发送支持不自动等于接收支持'),('B41 / B42','SVC 发布侧 / 订户侧','分别核对采样产生与接受能力')])+table(['原表 A.2 模型项目','内容','工程核对'],[('M1～M4','LD、LN、DATA、DataSet','对象和成员能力'),('M5 / M6','Substitution / Setting group control','支持取代和定值编辑流程'),('M7','Buffered report control','序号、报告时标、原因、数据集名、数据引用、溢出、EntryID、BufTm、IntgPd、GI'),('M8','Unbuffered report control','序号、时标、原因、数据集名、数据引用、BufTm、IntgPd、GI'),('M9 / M10 / M11','Log control / Log / Control','记录规则、查询和控制行为'),('M12 / M13','GOOSE / GSSE','GOOSE 中 entryID、DataRefInc 等原附录项目按 SCSM 核对；不能虚构为当前 GOOSE 标准线上必带字段'),('M14 / M15','Multicast / Unicast SVC','样本发布方式与支持能力'),('M16 / M17','Time / File transfer','准确度与文件能力')])+p('原表 A.3 的 60 个编号如下，Report 在 BRCB/URCB 两处分别列项；取代复用 SetDataValues，不算新增服务语义。SendGOOSEMessage、SendGSSEMessage、SendMSVMessage 标记 MC；目录、管理、控制、文件和 SendUSVMessage 等采用 TP。具体 M/O/c 条件应按原附录选定角色逐项填写，不把这份服务清单当成所有设备必选表。')+table(['编号','服务名','关联形态'],[(f'S{i}',s,'MC' if i in (35,40,45) else 'TP') for i,s in enumerate(SERVICES,1)])+p('报告的子项 S24-1～3、S27-1～3 分别为 dchg/qchg/dupd。附录还要求记录内部时钟分辨率、准确度和支持的 TimeStamp 分辨率，三者分别填写。正文的 TimeSynchronisation 模型不是这 60 个编号中额外虚构的 S61。')+table(['条件','原附录意义','阅读提示'],[('c1～c5','支持 LD/LN/DATA 以及数据集、取代、报告、日志、时间等时形成模型依赖','先检查选择的上层模型，再判下层必需项'),('c6','至少支持 BRCB/URCB 中一种','报告功能不等于两种必须同时实现'),('c7','至少支持 QueryLogByTime / QueryLogAfter 中一种','日志功能不等于所有查询接口均有'),('c8 / c9','GSE 发送模型选择与 TP 可用时的控制支持条件','发布与管理服务分开'),('c10','至少支持 SendMSVMessage / SendUSVMessage 中一种','多播和单播不是共同必选')])+p('PICS 是协议实现一致性声明，MICS 是模型实现声明，PIXIT 是测试所需额外信息。SCL Services 也是工程能力线索，但不能替代这三类资料和实际设备行为验证。')),
sec('workflows','4. 从需求到证据的工程阅读流程',table(['工程目标','先读配置','再查服务与状态','结论边界'],[('读取测量','LN/DO/DA 类型、FC=MX、单位/缩放','GetDataDefinition、GetDataValues、q/t','当前值可信需品质与来源'),('接收遥信事件','DataSet、RCB、DA 和 TrgOps','关联、RCB 保留、RptEna、报告字段','当前快照和历史恢复分开'),('恢复 SOE','BRCB、EntryID 选项与修订','最近 ID、缓存范围与溢出','不能保证容量之外的历史'),('查询装置历史','LogControl 及日志目标','GetLogStatusValues、范围/增量查询','无 Log 元素时先核实运行模型'),('切换定值组','SettingControl、SG/SE 数据','激活/编辑/确认各阶段结果','编辑不等于生效'),('解释 GOOSE/SV','发布块、成员、通信参数与订阅','有效期、修订、测试、同步/连续性','地址不等于实际业务含义'),('解释控制失败','ctlModel、CO/CF、反馈对象','失败阶段、ServiceError、AddCause','不能单个错误名就认定现场故障'),('取回记录文件','FileHandling 与设备文件说明','目录、属性、GetFile 结果','传输成功不证明格式/内容有效')])+p('同一模型变更要同步检查首页/术语、控制块引用、成员顺序、类型和订阅链。离线知识库提供这些静态解释，不执行现场数据访问、抓包、发包或控制，也不替代工程校验和受控试验。')),
sec('checklist','5. 示例、版次与验证边界',p('工程摘录为所给源 SCD 的局部片段；教学流程和 SVG 为原创。真实名称用于定位，描述文本只作文件证据，不据此补出未知电气业务。未观察到某元素只表示本文件未配置/未表达，不能外推设备或标准不支持。')+table(['本次检查','可确认','不据此声称'],[('PDF OCR + 关键表图核对','版次、章节、关键类型/参数与原文定位','正式勘误和后续所有版本全集'),('XML 结构与引用追踪','统计与展示例子的模型链','源 SCD 完整 XSD 合法、设备已加载'),('本地链接与静态资源','入口、章节、术语锚点的离线组织','当前设备网络或运行状态'),('页面窄屏与表图','浏览器展示可读性','现场通信和控制通过验收')]))],
'第 18～20 章（表 42～43），附录 A 表 A.1～A.3（PDF 页 117～122）；结合源 SCD 能力声明。',[('standard-part-7-2','回到主章'),('scd-acsi-evidence','工程证据'),('acsi-services','服务全表')])
# Keep legacy index IDs stable and enrich entries before the home search script runs.
existing_ids={'SCL':'scl','FCDA':'fcda','FC':'fc','DAType':'datype','CDC':'cdc','ACSI':'acsi','FCD':'fcd','BRCB':'part71-brcb','URCB':'part71-urcb','LCB':'part71-lcb','dchg':'trigger-dchg','qchg':'trigger-qchg','dupd':'trigger-dupd'}
entries=[]
for a,b,c,d,e,f,z in ABBR:
 entries.append({'id':existing_ids.get(a,'acsi72-'+a.lower().replace('-','_')),'zh':a+'（'+c+'）','en':b,'aliases':[a,c,b],'category':'ACSI 类型与服务','level':d,'summary':e,'related':['acsi','fc','fcda'],'href':'chapters/'+f+'.html#'+z})
for f,t,g in pages:entries.append({'id':'chapter-'+f,'zh':t,'en':'IEC 61850-7-2 ACSI guide','aliases':[g,'第7-2部分','7-2','ACSI'],'category':g,'level':'第 7-2 部分关联专题','summary':'早期标准基线、属性与服务、参考 SCD 和工程阅读边界。','related':['acsi','scd'],'href':'chapters/'+f+'.html'})
s='/* 第 7-2 部分增补；更新既有 ID，保持旧词条引用有效。 */\n(function () {\n  const additions = '+json.dumps(entries,ensure_ascii=False,indent=2)+';\n  const terms = window.IEC61850_TERMS;\n  for (const entry of additions) {\n    const old = terms.find(term => term.id === entry.id);\n    if (old) {\n      entry.aliases = [...new Set([...old.aliases, old.zh, ...entry.aliases])];\n      entry.related = [...new Set([...old.related, ...entry.related])].filter(id => id !== entry.id);\n      Object.assign(old, entry);\n    } else {\n      entry.related = entry.related.filter(id => id !== entry.id);\n      terms.push(entry);\n    }\n  }\n}());\n'
(OUT/'data/part72-terms.js').write_text(s,encoding='utf-8')
# Correct one confirmed baseline type in the older companion page.
f=OUT/'chapters/control-blocks-reference.html';s=f.read_text(encoding='utf-8');s=s.replace('CnfEdit BOOLEAN；LActTm EntryTime','CnfEdit BOOLEAN；LActTm TimeStamp（所给 7-2 表 22）');f.write_text(s,encoding='utf-8')
print('Generated',len(pages),'pages and',len(entries),'term enrichments')
